import { IconChartBar, IconCloudUpload, IconLayoutGrid, IconSettings, IconShield } from '@tabler/icons-vue';
export default {
  name: 'SysConfigTabs',
  props: {
    activeIndex: {
      type: String,
      default: 'status'
    },
    isCollapse: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      menuItems: [{
        index: 'status',
        icon: IconChartBar,
        titleKey: 'sysConfigTabs.systemStatus'
      }, {
        index: 'upload',
        icon: IconCloudUpload,
        titleKey: 'sysConfigTabs.uploadSettings'
      }, {
        index: 'security',
        icon: IconShield,
        titleKey: 'sysConfigTabs.securitySettings'
      }, {
        index: 'page',
        icon: IconLayoutGrid,
        titleKey: 'sysConfigTabs.pageSettings'
      }, {
        index: 'others',
        icon: IconSettings,
        titleKey: 'sysConfigTabs.otherSettings'
      }]
    };
  },
  methods: {
    handleSelect(index) {
      this.$emit('update:activeIndex', index);
      this.$emit('update:isCollapse', false);
    }
  },
  mounted() {
    this.$emit('update:isCollapse', false);
  }
};